const d = $input.first().json || {};
const wf = d.workflow || {};
const ex = d.execution || {};
const err = ex.error || {};
const workflow_name = String(wf.name || 'unknown workflow');
const failed_node = String((err.node && err.node.name) || ex.lastNodeExecuted || 'unknown node');
const mode = String(ex.mode || 'unknown');
const exec_id = String(ex.id || 'unknown');
const exec_url = String(ex.url || '');
const ts = new Date().toISOString();
let msg = String(err.message || 'no error message');
msg = msg
  .replace(/xox[abposr]-[A-Za-z0-9-]{10,}/g, '<redacted>')
  .replace(/eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{5,}/g, '<redacted>')
  .replace(/-----BEGIN[\s\S]*?PRIVATE KEY-----/g, '<redacted>')
  .replace(/\b[A-Fa-f0-9]{32,}\b/g, '<redacted>')
  .replace(/(bearer\s+)[A-Za-z0-9._~+/=-]{16,}/gi, '$1<redacted>')
  .replace(/((?:password|passwd|secret|api[_-]?key|token)\s*[:=]\s*)\S+/gi, '$1<redacted>');
const error_message = msg.slice(0, 300);
const safe = (s) => String(s).replace(/[^A-Za-z0-9_.:-]/g, '_').slice(0, 120);
const storm_key = `soc:erralert:${safe(workflow_name)}:${safe(failed_node)}`;
return [{ json: { workflow_name, failed_node, error_message, exec_id, exec_url, mode, ts, storm_key } }];

const b = $('Build Message').item.json;
const guard = $input.first().json || {};
const counter = Number(Object.values(guard)[0]);
const redisOk = Number.isInteger(counter) && counter >= 1;
const note = redisOk ? '' : ' _(storm guard unavailable)_';
const send = redisOk ? (counter === 1) : true;
const text = `:rotating_light: SOC automation failure: ${b.workflow_name} / ${b.failed_node}`;
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: ':rotating_light: SOC Automation Failure', emoji: true } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Workflow:*\n${b.workflow_name}` },
    { type: 'mrkdwn', text: `*Failed node:*\n${b.failed_node}` },
    { type: 'mrkdwn', text: `*Execution:*\n${b.exec_id}` },
    { type: 'mrkdwn', text: `*Mode:*\n${b.mode}` },
    { type: 'mrkdwn', text: `*Time (UTC):*\n${b.ts}${note}` }
  ] },
  { type: 'section', text: { type: 'mrkdwn', text: '*Error:*\n```' + b.error_message + '```' } }
];
if (b.exec_url) blocks.push({ type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Open execution' }, url: b.exec_url, action_id: 'open_exec' }] });
const payload = JSON.stringify({ channel: 'C0SLACKCHANNEL', text, blocks });
return [{ json: { ...b, storm_counter: redisOk ? counter : null, storm_guard_ok: redisOk, _send: send, _slack_payload: payload } }];
